CREATE TABLE `lit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bin2` binary(2) DEFAULT 0x00FF,
  `vb` varbinary(4) NOT NULL DEFAULT 'AB',
  `flags` bit(3) DEFAULT b'101',
  `mask` bit(4) NOT NULL DEFAULT b'1010',
  `hid` varchar(5) DEFAULT NULL /*!80023 INVISIBLE */ COMMENT '숨김',
  `touched` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP /*!80023 INVISIBLE */ COMMENT 't',
  `fixed_col` int /*!50606 STORAGE DISK */ /*!50606 COLUMN_FORMAT FIXED */ DEFAULT '1',
  `mem_col` int /*!50606 STORAGE MEMORY */ DEFAULT NULL,
  `dyn_col` varchar(10) /*!50606 COLUMN_FORMAT DYNAMIC */ DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_vb` (`vb`) KEY_BLOCK_SIZE=4 COMMENT 'k'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=COMPRESSED KEY_BLOCK_SIZE=8;
